"""Bundled assets keep the web client installable without a frontend build."""
HTML = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>VALORANT Tracker</title><link rel="stylesheet" href="/style.css"><script src="/app.js" defer></script></head>
<body><aside><a class="brand" href="/">V<span>TRACKER</span></a><p class="eyebrow">YOUR GAME, IN FOCUS</p>
<nav aria-label="Tracker views"><button data-command="rank" class="active">01 <span>Rank overview</span></button>
<button data-command="today">02 <span>Today's session</span></button><button data-command="matches">03 <span>Career</span></button>
<button data-command="stats">04 <span>Performance</span></button><button data-command="kd">05 <span>Kill / death</span></button>
<button data-command="hs">06 <span>Headshots</span></button><button data-command="hours">07 <span>Agent hours</span></button>
<button data-command="rr">08 <span>RR history</span></button><button data-command="last">09 <span>Last match</span></button>
<button data-command="profile">10 <span>Player profile</span></button></nav>
<div class="local"><i></i> LOCAL CLIENT <small>Powered by HenrikDev</small></div></aside>
<main><header><span class="eyebrow">VALORANT / PLAYER INTELLIGENCE</span><span class="tag">PERSONAL TRACKER</span></header>
<section class="intro"><p class="eyebrow">MAKE EVERY MATCH COUNT</p><h1 id="view-title">Your next rank<br>starts here.</h1><p id="view-description">Find your form. Track your climb. See the numbers behind your game.</p></section>
<form id="search"><div class="search-row"><label class="player-field">RIOT ID<input id="player" placeholder="Player#TAG" autocomplete="off" required maxlength="120"></label><button class="primary" id="submit" type="submit">Look up player <span>↗</span></button></div>
<div class="options"><label>REGION<select id="region"><option value="">Auto-detect</option><option>ap</option><option>eu</option><option>na</option><option>kr</option><option>br</option><option>latam</option></select></label>
<label>PLATFORM<select id="platform"><option value="pc">PC</option><option value="console">Console</option></select></label>
<label id="count-field">MATCHES<select id="count"><option value="5">5 matches</option><option value="10" selected>10 matches</option></select></label>
<label id="agent-field" hidden>AGENT<input id="agent" placeholder="Clove" maxlength="60"></label>
<label id="pages-field" hidden>HISTORY<select id="pages"><option value="1">Up to 10 games</option><option value="3" selected>Up to 30 games</option><option value="10">Up to 100 games</option></select></label>
<label id="utc-field" class="check" hidden><input type="checkbox" id="utc"> Use UTC</label></div></form>
<p id="status" role="status" aria-live="polite">Ready when you are.</p>
<section id="result" hidden><div class="result-heading"><div><p class="eyebrow">PLAYER REPORT</p><h2 id="result-name"></h2></div><span id="result-view" class="tag"></span></div><div id="cards" class="cards"></div><div id="details"></div><details><summary>Full report</summary><pre id="report"></pre></details></section>
<section id="empty" class="empty"><span class="crosshair">⌖</span><div><h2>A clearer view of your game.</h2><p>Enter your Riot ID to load real match data.<br>Stats are requested only when you click Look up player.</p></div></section>
<footer>For your account and consenting players. Not affiliated with Riot Games.<span>V / TRACKER</span></footer></main></body></html>'''

CSS = '''*{box-sizing:border-box}body{margin:0;background:#0d121b;color:#eef0f4;font:15px/1.5 "Segoe UI",Arial,sans-serif}button,input,select{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #7fe8d3;outline-offset:4px}[hidden]{display:none!important}aside{position:fixed;inset:0 auto 0 0;width:244px;background:#101722;border-right:1px solid #26303e;padding:34px 23px;display:flex;flex-direction:column}.brand{font-size:34px;font-weight:900;letter-spacing:-3px;color:#ff5966;text-decoration:none;display:flex;align-items:center;gap:15px}.brand span{font-size:17px;letter-spacing:3px;color:#eef0f4}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:#95a1b4}aside>.eyebrow{font-size:8px;margin:9px 0 38px}nav{display:grid;gap:5px}nav button{background:none;border:0;border-left:2px solid transparent;color:#8995a8;text-align:left;padding:12px 9px;font-size:11px;display:flex;gap:14px}nav button span{font-size:13px}nav button:hover{background:#192230;color:white}nav button.active{background:#251e29;border-left-color:#ff5966;color:#ff8590}.local{margin-top:auto;padding-top:30px;font-size:9px;letter-spacing:2px}.local i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#7fe8d3;margin-right:8px}.local small{display:block;color:#8d99aa;margin-top:8px;letter-spacing:0}main{margin-left:244px;max-width:1500px;padding:32px 6%}header{display:flex;justify-content:space-between;align-items:center}.tag{border:1px solid #334052;padding:6px 10px;color:#a6b4c6;font-size:10px;letter-spacing:1px}.intro{margin:60px 0 34px}.intro>.eyebrow{color:#ff7180}h1{font-size:clamp(36px,4.6vw,64px);line-height:1.07;letter-spacing:-2px;margin:18px 0;font-weight:750}.intro>p:last-child{color:#9ba8ba;max-width:600px}form{border:1px solid #303b4c;background:#131c29;padding:22px}.search-row{display:flex;gap:18px;align-items:end}label{font-size:9px;font-weight:700;letter-spacing:1.5px;color:#a3b1c4;display:flex;flex-direction:column;gap:7px}.player-field{flex:1}input,select{background:#0d1420;color:#eff4fb;border:1px solid #374458;padding:11px 12px;border-radius:2px;min-width:0;letter-spacing:0;font-size:14px}input:focus,select:focus{outline:2px solid #7fe8d3;outline-offset:1px}input::placeholder{color:#77869b}.primary{background:#ff5966;color:#101722;border:0;font-weight:750;padding:13px 22px;min-width:180px}.primary span{margin-left:20px}.primary:hover{background:#ff7b85}.primary:disabled{opacity:.55;cursor:wait}.options{display:flex;gap:18px;margin-top:20px;flex-wrap:wrap}.options label{min-width:115px}.options .check{flex-direction:row;align-items:center;align-self:end;padding:10px 0}#status{font-size:12px;color:#92a1b5;min-height:24px;margin:18px 0}#status.error{color:#ff929c}.result-heading{display:flex;justify-content:space-between;align-items:center;margin:30px 0 20px}.result-heading h2{font-size:25px;margin:4px 0}.result-heading p{margin:0}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{padding:21px;background:#141e2c;border:1px solid #29384b;border-top:2px solid #3c4e64}.card:first-child{border-top-color:#ff5966}.card small{display:block;color:#a5b1c3;font-size:10px;letter-spacing:1.5px}.card strong{display:block;font-size:29px;margin:10px 0 0;overflow-wrap:anywhere}.card p{font-size:11px;color:#93a5b9;margin:5px 0}.table-wrap{overflow:auto;border:1px solid #2a3749;margin-top:22px}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:13px}th,td{padding:14px 17px;text-align:left;border-bottom:1px solid #243042}th{color:#93a5b9;font-size:9px;letter-spacing:1.4px;background:#131c29}tr:last-child td{border:0}.win{color:#7fe8d3}.loss{color:#ff929c}.note{font-size:12px;color:#a4b2c5;margin:15px 0}details{margin-top:22px;border:1px solid #2a3749;padding:16px}summary{cursor:pointer;color:#a5b7cc;font-size:12px}pre{overflow:auto;font:12px/1.8 Consolas,monospace;color:#c1cede}.empty{border-top:1px solid #263345;padding:42px 10px;display:flex;align-items:center;gap:30px;margin-top:25px;color:#8e9db1}.empty h2{font-size:19px;color:#c6d1df;margin:0 0 8px}.empty p{font-size:13px}.crosshair{font-size:70px;color:#3e5068}footer{margin-top:65px;padding:20px 0;border-top:1px solid #263345;color:#8b9aaf;font-size:10px;display:flex;justify-content:space-between;gap:20px}footer span{letter-spacing:2px;white-space:nowrap}@media(min-width:1500px){main{margin-right:auto}}@media(max-width:900px){aside{width:190px;padding:24px 14px}main{margin-left:190px;padding:25px 5%}.cards{grid-template-columns:1fr}.intro{margin-top:40px}.search-row{flex-direction:column;align-items:stretch}.primary{width:100%}.tag{font-size:8px}}@media(max-width:600px){aside{position:static;width:auto;padding:18px;border-right:0;border-bottom:1px solid #26303e}.brand{font-size:27px}aside>.eyebrow,.local{display:none}nav{display:flex;overflow-x:auto;margin-top:16px;gap:7px}nav button{white-space:nowrap;padding:8px 10px}nav button span{font-size:12px}main{margin:0;padding:23px 18px}header .tag{display:none}h1{font-size:41px}.intro{margin-top:30px}.cards{grid-template-columns:1fr 1fr}.card{padding:15px}.card strong{font-size:23px}.empty{gap:16px}footer{margin-top:35px}}'''

JS = '''"use strict";
const $=id=>document.getElementById(id);
const titles={rank:"Rank overview",today:"Today's session",matches:"Career",stats:"Performance",kd:"Kill / death",hs:"Headshots",hours:"Agent hours",rr:"RR history",last:"Last match",profile:"Player profile"};
let command="rank",busy=false;
function selectCommand(next){if(busy)return;command=next;document.querySelectorAll("nav button").forEach(b=>{b.classList.toggle("active",b.dataset.command===command);b.setAttribute("aria-pressed",b.dataset.command===command)});$("view-title").textContent=titles[command];$("view-description").textContent=command==="hours"?"Time on your agent, measured across available recent matches. This is not lifetime playtime.":"Find your form. Track your climb. See the numbers behind your game.";$("agent-field").hidden=command!=="hours";$("pages-field").hidden=command!=="hours";$("agent").required=command==="hours";$("count-field").hidden=!["matches","stats","kd","hs","rr"].includes(command);$("utc-field").hidden=!["today","rr"].includes(command);$("status").textContent="Ready. Look up your player to load this view.";$("status").className="";$("result").hidden=true;$("empty").hidden=false;}
document.querySelectorAll("nav button").forEach(b=>b.addEventListener("click",()=>selectCommand(b.dataset.command)));
function card(label,value,note=""){const el=document.createElement("div");el.className="card";for(const [tag,text] of [["small",label],["strong",value],["p",note]]){const node=document.createElement(tag);node.textContent=text;el.append(node)}$("cards").append(el)}
function table(headers,rows){const wrap=document.createElement("div");wrap.className="table-wrap";const t=document.createElement("table"),head=document.createElement("thead"),body=document.createElement("tbody");const tr=document.createElement("tr");headers.forEach(h=>{const el=document.createElement("th");el.textContent=h;tr.append(el)});head.append(tr);rows.forEach(row=>{const r=document.createElement("tr");row.forEach(value=>{const el=document.createElement("td");el.textContent=value??"--";if(value==="WIN")el.className="win";if(value==="LOSS")el.className="loss";r.append(el)});body.append(r)});t.append(head,body);wrap.append(t);$("details").append(wrap)}
function note(text){const p=document.createElement("p");p.className="note";p.textContent=text;$("details").append(p)}
const signed=n=>n>=0?"+"+n:String(n),fixed=(n,d=2)=>n==null?"--":n.toFixed(d);
function render(result){const d=result.data;$("cards").replaceChildren();$("details").replaceChildren();$("result-name").textContent=d.account.name+"#"+d.account.tag;$("result-view").textContent=titles[result.command];$("report").textContent=result.text;
if(d.rank){card("CURRENT RANK",d.rank.current?.tier?.name??"Unrated");card("RANK RATING",d.rank.current?.rr??"--","RR in current rank");card("LAST CHANGE",signed(d.rank.current?.last_change??0),"RR from last match")}
else if(d.today){const s=d.today;card("NET RR",signed(s.net_rr),s.missing_rr?"Partial: RR missing for "+s.missing_rr+" games":"Gained "+signed(s.rr_gained)+" / lost "+s.rr_lost);card("SESSION RECORD",s.wins+"W / "+s.losses+"L",s.draws+" draws · "+s.unknown_results+" unknown");card("MATCHES",s.matches,s.date+" · "+s.timezone);table(["MAP","RESULT","RR CHANGE"],s.games.map(g=>[g.map,g.result,g.rr_change==null?"--":signed(g.rr_change)]));(d.notes||[]).forEach(note)}
else if(d.stats){const s=d.stats;card("K / D",fixed(s.kd),s.kills+" kills / "+s.deaths+" deaths");card("HEADSHOT RATE",s.headshot_pct==null?"--":fixed(s.headshot_pct,1)+"%",s.headshots+" head hits");card("WIN RATE",s.win_rate==null?"--":fixed(s.win_rate,1)+"%",s.wins+"W / "+s.losses+"L / "+s.draws+"D");note("Sample: "+s.matches+" recent completed competitive matches.");table(["AGENT","GAMES"],Object.entries(s.agents))}
else if(d.hours){const h=d.hours;card("AGENT HOURS",fixed(h.hours),h.agent);card("AGENT MATCHES",h.agent_matches,"Completed matches");card("GAMES SCANNED",h.scanned_matches,"Recent history across all queues");note(h.scope);if(h.oldest_match)note("Sample: "+h.oldest_match+" to "+h.newest_match);if(h.missing_duration)note("Partial: duration is missing for "+h.missing_duration+" matches.");if(!h.agent_matches)note("No matching agent games found. Check spelling or expand the history sample.")}
else if(d.history){card("RR UPDATES",d.history.length,"Available recent history");table(["DATE (UTC)","MAP","CHANGE","RANK AFTER","RR"],d.history.map(h=>[h.date,h.map?.name,signed(h.last_change),h.tier?.name,h.rr]))}
else if(d.matches){card("MATCHES",d.matches.length,"Available recent games");table(["MAP","AGENT","RESULT","K / D / A"],d.matches.map(m=>{const p=m.players.find(p=>p.puuid===d.account.puuid);const t=m.teams.find(t=>t.team_id===p?.team_id);let result="UNKNOWN";if(m.metadata.is_completed&&t){result=t.rounds?.won!=null&&t.rounds?.won===t.rounds?.lost?"DRAW":t.won===true?"WIN":t.won===false?"LOSS":"UNKNOWN"}return [m.metadata.map?.name,p?.agent?.name,result,p?[p.stats.kills,p.stats.deaths,p.stats.assists].join(" / "):"--"]}));if(!d.matches.length)note("No matches available for this player and queue.")}
else{card("ACCOUNT LEVEL",d.account.account_level??"--");card("REGION",d.account.region?.toUpperCase()??"--");card("PLATFORMS",(d.account.platforms||[]).join(" / "));note("Last updated: "+(d.account.updated_at??"Unknown"))}
$("result").hidden=false;$("empty").hidden=true;}
$("search").addEventListener("submit",async event=>{event.preventDefault();if(busy)return;busy=true;$("submit").disabled=true;$("status").className="";$("status").textContent="Loading player data… This can take a moment.";$("result").hidden=true;document.querySelectorAll("nav button").forEach(b=>b.disabled=true);try{const response=await fetch("/api/query",{method:"POST",headers:{"Content-Type":"application/json","X-Tracker-Request":"1"},body:JSON.stringify({command,player:$("player").value.trim(),region:$("region").value,platform:$("platform").value,count:Number($("count").value),pages:Number($("pages").value),agent:$("agent").value.trim(),utc:$("utc").checked})});const data=await response.json();if(!response.ok)throw new Error(data.error||"Lookup failed.");render(data);$("status").textContent="Updated just now · "+titles[command];}catch(error){$("status").className="error";$("status").textContent=error.message||"Could not connect. Check the local server."}finally{busy=false;$("submit").disabled=false;document.querySelectorAll("nav button").forEach(b=>b.disabled=false)}});
'''
